CREATE OR REPLACE FUNCTION public.notify_on_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_href text;
begin
  v_href := case
    when new.order_id is not null then '/orders/' || new.order_id
    else '/orders'
  end;

  perform public.notify(
    new.recipient_id, 'message', 'marketplace',
    'Message from ' || public.actor_name(new.sender_id),
    left(new.body, 140), v_href, new.sender_id
  );
  return new;
end;
$function$;

grant execute on function public.notify_on_message() to anon;
grant execute on function public.notify_on_message() to authenticated;
grant execute on function public.notify_on_message() to public;
grant execute on function public.notify_on_message() to service_role;
